function seedDemo(){
 S.financeLedger={available:false};S.loadError='';S.loading=false;
 const sample=[['Marina Santos','Criar uma rotina alimentar','Intolerância à lactose'],['Lucas Oliveira','Melhorar a disposição','Vegetariano'],['Beatriz Costa','Organizar as refeições',''],['Rafael Mendes','Nutrição esportiva',''],['Ana Luiza','Alimentação equilibrada','Alergia a amendoim'],['Pedro Alves','Ganhar consistência','']];
 S.patients=sample.map((p,i)=>({id:`demo-${i}`,clinic_id:S.clinic.id,clinician_id:'demo',name:p[0],goal:p[1],restrictions:p[2],email:`paciente${i+1}@exemplo.test`,created_at:new Date().toISOString()}));S.selected=S.patients[0].id;
 S.logs=[];for(let p of S.patients)for(let i=1;i<13;i++){let d=new Date();d.setDate(d.getDate()-i);if((i+S.patients.indexOf(p))%4!==0)S.logs.push({patient_id:p.id,day:localDay(d),water_ml:1750,meals:['breakfast','lunch','dinner'],followed:true,weight:null,sleep:7.5,mood:'good',note:i===1?'Consegui organizar as refeições esta semana.':''});}
 S.plans=S.patients.map(p=>({id:uid(),patient_id:p.id,status:'published',version:1,data:samplePlan(p)}));S.messages=[{id:uid(),patient_id:S.selected,sender_id:'demo',body:'Marina, como está a sua rotina? Se precisar, podemos ajustar os horários das refeições.',created_at:new Date().toISOString()}];
 let d=new Date();d.setHours(14,30,0,0);S.appointments=[{id:uid(),patient_id:S.selected,start_at:d.toISOString(),note:'Consulta de retorno'}];S.challenges=[{id:uid(),title:'Diário em dia',metric:'nutriDias',target:7},{id:uid(),title:'Água e rotina',metric:'habitosAgua',target:5}];P.seed();
}
function localDay(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function samplePlan(p){return {v:1,id:uid(),titulo:'Minha rotina alimentar',objetivo:p.goal,orientacoes:'Organize os horários conforme sua rotina. Converse com sua nutricionista sobre qualquer dificuldade.',responsavel:S.clinic.professional_name,crn:S.clinic.crn,aguaMl:2000,refeicoes:[{id:'breakfast',hora:'07:30',titulo:'Café da manhã',itens:[food('Pão integral','2 fatias',1,124,5,23,2),food('Ovo cozido','2 unidades',1,140,12,1,10),food('Mamão','1 porção',1,60,1,15,0)]},{id:'lunch',hora:'12:30',titulo:'Almoço',itens:[food('Arroz cozido','100 g',1,130,3,28,0),food('Feijão','1 concha',1,77,5,14,0),p.restrictions==='Vegetariano'?food('Tofu','150 g',1,114,12,3,7):food('Frango grelhado','100 g',1,165,31,0,4),food('Salada de folhas','1 porção',1,20,1,3,0)]},{id:'snack',hora:'16:00',titulo:'Lanche da tarde',itens:[food('Banana','1 unidade',1,89,1,23,0),food('Aveia','30 g',1,117,5,20,2)]},{id:'dinner',hora:'19:30',titulo:'Jantar',itens:[p.restrictions==='Vegetariano'?food('Grão-de-bico cozido','150 g',1,246,13,41,4):food('Tilápia grelhada','150 g',1,192,39,0,4),food('Batata-doce','150 g',1,129,2,30,0),food('Legumes cozidos','1 porção',1,60,3,10,1)]}]};}
function food(nome,porcao,qtd,k,pt,cb,g){return {id:uid(),alimId:nome,nome,porcao,qtd,k,pt,cb,g};}
function toast(s){if($('#modal')?.open&&$('#modal-feedback')){$('#modal-feedback').textContent=s;$('#modal-feedback').hidden=false;}$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').style.display='none',3800);}
function patient(){return S.patients.find(p=>p.id===S.selected)||S.patients[0];}
function published(p=patient()){return S.plans.find(x=>x.patient_id===p?.id&&x.status==='published');}
function logs(p=patient()){return S.logs.filter(x=>x.patient_id===p?.id);}
function logToday(){return logs().find(x=>x.day===today())||{patient_id:patient()?.id,day:today(),water_ml:0,meals:[],followed:false};}
function stats(p=patient()){return careSummary({patientId:p?.id,logs:S.logs,records:S.records,today:today(),clinicGoal:S.clinic.weekly_goal});}
function shell(content){
 const isPatient=S.role==='patient',nav=isPatient?navPatient:[...navNutri,['more','☰','Menu']];
 const active=isPatient&&!navPatient.some(x=>x[0]===S.page)?'more':S.page;
 const logo=S.clinic.logo?`<img class="logo" src="${esc(S.clinic.logo)}" alt="${esc(S.clinic.name)}">`:`<div class="wordmark"><span class="mark">T</span>torque<span> nutri</span></div>`;
 const accountActions=S.demo?`${demoRole?'':`<button class="btn small ghost" data-action="switch-role">${isPatient?'Ver app da nutri':'Ver app do paciente'}</button>`}<button class="btn small" data-action="auth">Entrar na minha conta</button>`:'<button class="btn small ghost" data-action="refresh">Atualizar</button><button class="btn small" data-action="logout">Sair</button>';
 const theme='<button class="btn icon-button" data-action="theme" aria-label="Alternar tema">◐</button>';
 const top=isPatient?`<header class="topbar patient-topbar"><button type="button" class="patient-home-brand" data-page="today" aria-label="Torque Nutri, início">torque<span> nutri</span></button><div class="top-actions">${theme}${P.notificationButton()}</div></header>`:`<header class="topbar"><span class="context">${ecosystemUrl()?'<a href="'+esc(ecosystemUrl())+'">Torque On</a> / ':''}${esc(S.clinic.name)} / Consultório</span><div class="wordmark mobile-role">torque<span> nutri</span></div><div class="top-actions">${accountActions}${theme}<div class="avatar">${initials(S.clinic.professional_name)}</div></div></header>`;
 const loadNotice=!S.demo&&(S.loadError||S.offline)?`<div class="notice warning" role="status">${esc(S.loadError||(S.offline?'Sem conexão. Exibindo a última leitura salva neste aparelho.':''))}</div>`:'';
 const accountMenu=isPatient&&S.page==='more'?'<section class="card patient-account-actions"><h2>Minha conta</h2><div class="actions">'+accountActions+'</div></section>':'';
 $('#app').innerHTML=`<div class="layout ${isPatient?'patient-layout':''}"><aside class="sidebar">${logo}<div><div class="nav-label">${isPatient?'Meu acompanhamento':'Meu consultório'}</div><nav aria-label="Navegação principal">${nav.map(([id,ic,title])=>`<button class="nav-btn ${active===id?'active':''} ${id==='more'&&!isPatient?'mobile-only':''}" data-page="${id}" ${active===id?'aria-current="page"':''} ${isPatient&&id==='food'?'aria-label="Plano alimentar"':''}><span class="nav-icon" aria-hidden="true">${P.icon?.(id)||ic}</span><span class="nav-text">${title}</span></button>`).join('')}</nav></div><div class="sidebar-foot"><b>${esc(S.clinic.name)}</b><p>${esc(S.clinic.professional_name)}</p><span class="pill green">${S.demo?'Modo demonstração':'Conta conectada'}</span></div></aside><main class="main ${isPatient?'patient-main':''}">${top}${S.demo?'<div class="notice demo-notice">'+(demoRole==='patient'?'Demonstração do paciente. ':demoRole==='nutri'?'Demonstração do nutricionista. ':'')+'Dados fictícios para explorar a plataforma. Nenhum registro da demonstração é enviado ao consultório.</div>':''}${loadNotice}${content}${accountMenu}</main></div>`;bind();
}
function heading(k,title,sub,action=''){return `<div class="heading"><div><div class="eyebrow">${k}</div><h1>${title}</h1>${sub?`<p class="sub">${sub}</p>`:''}</div>${action}</div>`;}
function overview(){const all=S.patients;let active=all.filter(p=>published(p));let follow=all.filter(p=>stats(p).days>0);return heading('Seu consultório',`Bom dia, ${esc(S.clinic.professional_name.split(' ')[1]||S.clinic.professional_name)}.`,`Um olhar para a rotina dos seus pacientes.`,`<button class="btn primary" data-action="new-patient">+ Novo paciente</button>`)+`<div class="stats">${[[all.length,'Pacientes','em acompanhamento'],[active.length,'Planos publicados','disponíveis no app'],[follow.length,'Check-ins nesta semana','pacientes com registros'],[S.appointments.filter(x=>x.start_at.slice(0,10)===today()).length,'Consultas hoje','na sua agenda']].map(([n,l,s])=>`<div class="stat"><div class="stat-label">${l}<span aria-hidden="true">◈</span></div><div class="stat-num">${n}</div><div class="stat-note">${s}</div></div>`).join('')}</div><div class="cols"><div><section class="card"><div class="card-head"><h2>Acompanhamento dos pacientes</h2><button class="btn small ghost" data-page="patients">Ver todos</button></div>${all.slice(0,5).map(p=>patientRow(p)).join('')||'<div class="empty">Cadastre seu primeiro paciente para começar o acompanhamento.</div>'}</section><section class="card"><div class="card-head"><h2>Registros recentes</h2><span class="pill">Últimos check-ins</span></div>${S.logs.filter(x=>x.note).slice(-3).reverse().map(x=>`<div class="activity"><span class="activity-icon">✓</span><div><p><b>${esc(all.find(p=>p.id===x.patient_id)?.name)}</b> registrou um check-in.</p><p class="sub">${esc(x.note)}</p><small>${dateLabel(x.day)}</small></div></div>`).join('')||'<div class="empty">Os check-ins respondidos pelos pacientes aparecerão aqui.</div>'}</section></div><div><section class="card journey"><div class="eyebrow">Cuidado que vira rotina</div><h2>Pequenas ações.<br>Conquistas que ficam.</h2><p class="sub">Diário, água e check-ins valem pontos. Cada paciente avança no próprio ritmo.</p><div class="week">${['Diário','Água','Sono'].map(x=>`<span class="pill green">${x}</span>`).join('')}</div><button class="btn" data-page="challenges">Configurar gamificação</button></section><section class="card"><div class="card-head"><h2>Próximas consultas</h2></div>${S.appointments.slice().sort((a,b)=>a.start_at.localeCompare(b.start_at)).slice(0,3).map(x=>`<div class="activity"><span class="activity-icon">▦</span><div><p><b>${esc(all.find(p=>p.id===x.patient_id)?.name)}</b></p><small>${dateLabel(x.start_at)} · ${new Date(x.start_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</small><small>${esc(x.note)}</small></div></div>`).join('')||'<div class="empty">Nenhuma consulta agendada.</div>'}<button class="btn ghost small" data-page="appointments">Abrir agenda</button></section></div></div>`;}
function patientRow(p){const st=stats(p);return `<div class="patient-row"><div class="avatar">${initials(p.name)}</div><div class="grow"><button class="btn ghost small" style="padding:0;border:0" data-patient="${p.id}">${esc(p.name)}</button><small>${esc(p.goal||'Objetivo a definir')}</small></div><div class="row-end"><b>${st.days}/${st.target} dias com cuidado</b><small class="status ${st.days<2?'warn':''}">${st.days<2?'Vamos conversar':'Rotina acompanhada'}</small></div><button class="btn small ghost" data-patient="${p.id}" aria-label="Abrir paciente ${esc(p.name)}">Abrir</button></div>`;}
let renderedSection='';
function brandInk(color){const rgb=/^#[0-9a-f]{6}$/i.test(color)?color.slice(1).match(/../g).map(x=>parseInt(x,16)/255):[.36,.88,.70];const l=rgb.map(x=>x<=.04045?x/12.92:((x+.055)/1.055)**2.4);return .2126*l[0]+.7152*l[1]+.0722*l[2]>.179?'#101b15':'#ffffff';}
function render(){applyReminderRoute();const section=S.page+'|'+S.selected;if(section!==renderedSection){renderedSection=section;requestAnimationFrame(()=>scrollTo(0,0));}document.documentElement.style.setProperty('--brand',S.clinic.color||'#5de0b4');document.documentElement.style.setProperty('--on-brand',brandInk(S.clinic.color||'#5de0b4'));if(S.page==='auth')return authView();if(S.page==='join')return joinView();if(S.page==='invite')return inviteSessionView();const views={overview,patients:patientsView,profile:profileView,plans:plansView,editor:editorView,appointments:appointmentsView,challenges:challengesView,brand:brandView,today:todayView,food:foodView,progress:progressView,achievements:achievementsView,chat:chatView,...P.views};shell((views[S.page]||overview)());bindSpecial();P.bind();if(S.busy)lockUI();}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{if(S.busy){toast('Aguarde concluir a ação atual.');return;}if(S.page==='editor')syncEditor();S.page=b.dataset.page;render();});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>run(()=>action(b.dataset.action)));document.querySelectorAll('[data-patient]').forEach(b=>b.onclick=()=>{if(S.busy)return;if(S.page==='editor')syncEditor();S.selected=b.dataset.patient;S.page='profile';render();});document.querySelectorAll('[data-edit-plan]').forEach(b=>b.onclick=()=>run(()=>openEditor(b.dataset.editPlan)));document.querySelectorAll('[data-chat-patient]').forEach(b=>b.onclick=()=>{if(S.busy)return;S.selected=b.dataset.chatPatient;S.page='chat';render();});}
async function run(fn){if(S.busy)return;S.busy=true;lockUI();try{await fn();}catch(e){console.error(e);if(S.loadError&&!$('#modal')?.open)render();toast(e.message||'Não foi possível concluir. Tente novamente.');}finally{S.busy=false;unlockUI();}}
async function action(a){
 if(a==='switch-role'){if(demoRole)return;S.role=S.role==='nutri'?'patient':'nutri';S.page=S.role==='nutri'?'overview':'today';render();}
 if(a==='theme'){document.body.classList.toggle('theme-light');localStorage.setItem('torque-nutri-theme',document.body.classList.contains('theme-light')?'light':'dark');}
 if(a==='auth'){if(demoRole){const url=new URL(appBase.href);url.searchParams.set('entrar','1');url.searchParams.set('perfil',demoRole);location.assign(url.href);return;}S.page='auth';render();}
 if(a==='new-patient')newPatient();
 if(a==='refresh'){await loadData();render();toast('Acompanhamento atualizado.');}
 if(a==='logout')await logoutAccount();
 if(a==='water'){await saveLog({waterDelta:250});toast('Mais um copo registrado.');}
 if(a==='water-undo'){await saveLog({waterDelta:-250});}
 if(a==='followed'){await saveLog({followed:!logToday().followed});if(navigator.onLine||S.demo)toast(logToday().followed?'Sua confirmação de plano seguido foi registrada.':'Confirmação de plano seguido removida.');}
 if(a==='checkin')checkinModal();
 if(a==='new-appointment')appointmentModal();
 if(a==='new-challenge')challengeModal();
 if(a==='save-draft')await saveDraft();
 if(a==='publish-plan')reviewDraft();
 if(a==='add-meal'){syncEditor();if(S.edit.refeicoes.length>=12)throw Error('Use até 12 refeições por plano.');S.edit.refeicoes.push({id:uid(),hora:'12:00',titulo:'Nova refeição',itens:[]});cacheEditor();render();}
 if(a==='invite')await showInvite();if(a==='discard-local'){if(!confirm('Descartar as alterações não salvas e reabrir a versão salva?'))return;sessionStorage.removeItem(draftKey());await openEditor(S.selected);}
 if(a==='print'){const p=published()?.data;if(!p)throw Error('Publique um plano antes de imprimir.');printPlan(p);}
}
function patientsView(){return heading('Cuidado individual','Seus pacientes','Planos e registros, no contexto de cada pessoa.','<button class="btn primary" data-action="new-patient">+ Novo paciente</button>')+`<label class="search">Buscar paciente<input id="patient-search" placeholder="Nome ou objetivo"></label><div class="patient-grid" id="patient-grid">${patientTiles(S.patients)}</div>`;}
function patientTiles(pp){return pp.map(p=>{const st=stats(p);return `<button class="patient-tile" data-patient="${p.id}"><span class="tile-head"><span class="avatar">${initials(p.name)}</span><span><b>${esc(p.name)}</b><span class="sub" style="display:block;margin:4px 0 0">${esc(p.goal||'Objetivo a definir')}</span></span></span><span class="pill ${published(p)?'green':''}">${published(p)?'Plano publicado':'Plano a preparar'}</span><span><span class="stat-label">Rotina desta semana <b>${st.days}/${st.target} dias com cuidado</b></span><span class="progress" style="display:block"><i style="width:${Math.min(100,st.days/S.clinic.weekly_goal*100)}%"></i></span></span></button>`;}).join('')||'<div class="empty">Nenhum paciente encontrado.</div>';}
function profileView(){const p=patient();if(!p)return patientsView();const pl=published(p);const st=stats(p);return heading('Paciente',esc(p.name),esc(p.goal),' <button class="btn primary" data-edit-plan="'+p.id+'">Editar plano alimentar</button>')+`<div class="actions" style="margin-bottom:22px"><button class="btn ghost small" data-page="patients">Voltar aos pacientes</button><button class="btn small" data-action="invite">Gerar convite do paciente</button><button class="btn small" data-chat-patient="${p.id}">Abrir conversa</button><button class="btn small" data-action="edit-patient">Editar cadastro</button></div><div class="cols"><div><section class="card"><div class="card-head"><h2>Perfil e acompanhamento</h2><span class="pill green">${pl?'Plano disponível':'Em preparação'}</span></div><div class="summary-line"><span>E-mail</span><span>${esc(p.email||'Não informado')}</span></div><div class="summary-line"><span>Objetivo</span><span>${esc(p.goal||'A definir')}</span></div><div class="summary-line"><span>Restrições e preferências</span><span>${esc(p.restrictions||'Não informado')}</span></div><p class="sub">Confirme a anamnese na consulta antes de definir o plano.</p></section><section class="card"><div class="card-head"><h2>Check-ins recebidos</h2></div>${logs(p).filter(x=>x.mood||x.note||x.weight).slice().sort((a,b)=>b.day.localeCompare(a.day)).slice(0,8).map(x=>`<div class="activity"><span class="activity-icon">✓</span><div><p>${dateLabel(x.day)} · ${esc(moodName(x.mood)||'Registro diário')}</p><p class="sub">${esc(x.note||'')}${x.weight?` · Peso registrado: ${x.weight} kg`:''}</p><small>${x.water_ml||0} ml de água · ${(x.meals||[]).length} refeições registradas</small></div></div>`).join('')||'<div class="empty">Nenhum check-in recebido.</div>'}</section></div><div><section class="card journey"><div class="eyebrow">Constância</div><div class="big-number" style="margin:16px 0">${st.days}<span style="font-size:18px;color:var(--muted)"> / ${S.clinic.weekly_goal} dias</span></div><p class="sub">Meta semanal de acompanhamento</p><div class="progress"><i style="width:${Math.min(100,st.days/S.clinic.weekly_goal*100)}%"></i></div><span class="pill purple">${st.xp} XP acumulados</span></section><section class="card"><h2>Plano atual</h2>${pl?`<p class="sub">${esc(pl.data.titulo)}</p><span class="pill">Versão ${pl.version}</span><p class="sub">${pl.data.refeicoes.length} refeições · ${pl.data.aguaMl||2000} ml de água</p><button class="btn small" data-edit-plan="${p.id}">Revisar prescrição</button>`:'<p class="sub">Prepare e publique o plano para disponibilizá-lo no app do paciente.</p>'}</section></div></div>`;}
function prescriptionIcon(name){const paths={back:'<path d="m14 6-6 6 6 6M8 12h12"/>',up:'<path d="m6 14 6-6 6 6M12 8v12"/>',down:'<path d="m6 10 6 6 6-6M12 4v12"/>',copy:'<rect x="8" y="8" width="12" height="12" rx="3"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',plus:'<path d="M12 5v14M5 12h14"/>',remove:'<path d="M5 7h14M10 11v6M14 11v6M8 7V4h8v3M7 7l1 13h8l1-13"/>',swap:'<path d="M4 7h15m-4-4 4 4-4 4M20 17H5m4-4-4 4 4 4"/>',plan:'<rect x="5" y="3" width="14" height="18" rx="3"/><path d="M9 8h6M9 12h6M9 16h4"/>',check:'<path d="m5 12 4 4L19 6"/>'};return `<svg class="prescription-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.plan}</svg>`;}
function plansView(){
 const publishedCount=S.patients.filter(p=>published(p)).length;
 return `<div class="prescription-workspace prescription-library">${heading('Prescrição','Planos alimentares','Planeje cada refeição no contexto de quem você cuida.')}<section class="prescription-library-intro"><div class="prescription-intro-symbol">${prescriptionIcon('plan')}</div><div><h2>Do rascunho à rotina</h2><p class="sub">Edite, revise e publique. O paciente continua com a versão publicada até você disponibilizar a próxima.</p></div><span class="pill">${publishedCount} de ${S.patients.length} com plano publicado</span></section><section class="prescription-plan-list">${S.patients.map(p=>{const plan=published(p),draft=S.plans.find(x=>x.patient_id===p.id&&x.status==='draft'),meals=plan?.data?.refeicoes||[];return `<article class="patient-row prescription-plan-row"><span class="avatar">${initials(p.name)}</span><div class="grow"><h2>${esc(p.name)}</h2><p class="prescription-plan-title">${esc(plan?.data.titulo||'Plano alimentar a preparar')}</p><small>${plan?`${meals.length} ${meals.length===1?'refeição':'refeições'} na versão publicada`:esc(p.goal||'Comece a prescrição deste paciente')}</small></div><div class="prescription-plan-state"><span class="pill ${plan?'green':''}">${plan?'Publicado · v'+plan.version:'Sem publicação'}</span>${draft?'<small>Rascunho salvo para revisar</small>':''}</div><button class="btn prescription-edit-plan" data-edit-plan="${p.id}">${prescriptionIcon('plan')}${plan||draft?'Editar plano':'Criar plano'}</button></article>`;}).join('')||'<div class="card empty">Cadastre um paciente para preparar o primeiro plano.</div>'}</section></div>`;
}
async function openEditor(id){S.selected=id;S.prescriptionDay=today();const draft=S.plans.find(x=>x.patient_id===id&&x.status==='draft'),pub=published();S.draftId=draft?.id;S.expectedVersion=draft?.version||1;S.edit=structuredClone(draft?.data||pub?.data||{v:1,id:uid(),titulo:'Plano alimentar',objetivo:patient().goal,orientacoes:'',responsavel:S.clinic.professional_name,crn:S.clinic.crn,aguaMl:2000,refeicoes:[]});S.localDirty=false;try{const saved=JSON.parse(sessionStorage.getItem(draftKey())||'null');if(saved?.data){S.edit=saved.data;S.draftId=saved.draftId;S.expectedVersion=saved.expectedVersion;S.localDirty=true;}}catch{}S.page='editor';render();}
function editorContext(){
 const p=patient(),anamnesis=latestAnamnesis(S.records,p.id),d=anamnesis?.data||{};
 const fields=[['Objetivo do acompanhamento',p.goal],['Restrições do cadastro',p.restrictions],['Alergias e intolerâncias',d.allergies],['Condições de saúde',d.conditions],['Medicamentos e suplementos',d.medications],['Preferências e aversões',d.preferences],['Rotina e horários',d.routine],['Exames informados',d.exams]];
 return `<details class="prescription-context"><summary>Contexto nutricional<span class="prescription-disclosure-hint">Consultar</span></summary><div class="prescription-context-content"><p class="sub">${anamnesis?`Anamnese de ${dateLabel(anamnesis.updated_at||anamnesis.created_at||today())} · versão ${anamnesis.version||1}`:'Anamnese ainda não registrada.'}</p><dl>${fields.filter(([,value])=>value).map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl><div class="actions">${anamnesis?`<button class="btn small ghost" data-x="record-edit" data-id="${esc(anamnesis.id)}">Atualizar anamnese</button>`:'<button class="btn small ghost" data-x="anamnesis">Registrar anamnese</button>'}<button class="btn small ghost" data-follow-page="journal" data-follow-patient="${esc(p.id)}">Consultar diário</button></div></div></details>`;
}
function editorMeal(r,ri,count){
 const days=Array.isArray(r.dias)&&r.dias.length?r.dias:[0,1,2,3,4,5,6],total=prescribedTotals(r.itens);
 return `<section class="meal-editor prescription-meal" aria-labelledby="prescription-meal-${ri}"><header class="prescription-meal-head"><div class="prescription-meal-title"><span class="prescription-meal-number">${String(ri+1).padStart(2,'0')}</span><div><h2 id="prescription-meal-${ri}">Refeição ${ri+1}</h2><span class="prescription-meal-energy"><b data-meal-total="${ri}">${nutrientLabel(total.k)}</b> kcal · ${r.itens.length} ${r.itens.length===1?'alimento':'alimentos'}</span></div></div><div class="prescription-meal-tools"><div class="prescription-move-tools" role="group" aria-label="Ordem da refeição ${ri+1}"><button class="btn small ghost prescription-icon-btn" data-move-meal="${ri}:-1" aria-label="Subir refeição ${esc(r.titulo)}" ${ri===0?'disabled':''}>${prescriptionIcon('up')}</button><button class="btn small ghost prescription-icon-btn" data-move-meal="${ri}:1" aria-label="Descer refeição ${esc(r.titulo)}" ${ri===count-1?'disabled':''}>${prescriptionIcon('down')}</button></div><button class="btn small ghost" data-duplicate-meal="${ri}">${prescriptionIcon('copy')}Duplicar refeição</button></div></header><div class="prescription-meal-body"><div class="form-grid prescription-meal-fields"><label>Nome da refeição<input data-meal-title="${ri}" value="${esc(r.titulo)}" maxlength="120"></label><label>Horário<input type="time" data-meal-time="${ri}" value="${esc(r.hora)}"></label></div><fieldset class="prescription-days"><legend>Dias desta refeição</legend><div class="prescription-week">${WEEKDAYS.map((label,day)=>`<label class="prescription-day"><input type="checkbox" data-meal-day="${ri}:${day}" ${days.includes(day)?'checked':''}><span>${label}</span></label>`).join('')}</div><p class="sub">Sem seleção, a refeição vale para todos os dias.</p></fieldset><div class="prescription-foods">${r.itens.map((it,ii)=>`<article class="prescription-food"><div class="prescription-food-heading"><div><h3>${esc(it.nome)}</h3><p data-food-portion="${ri}:${ii}">${esc(it.measurement?formatFoodQuantity(it):it.porcao)}</p></div><button class="btn small ghost prescription-icon-btn" data-remove-food="${ri}:${ii}" aria-label="Remover ${esc(it.nome)}">${prescriptionIcon('remove')}</button></div><div class="prescription-food-values"><div class="prescription-food-nutrients"><b><span class="prescription-food-energy-value" data-food-nutrient="${ri}:${ii}:k">${nutrientLabel(prescribedTotals([it]).k)}</span> <span>kcal</span></b><span>P <span data-food-nutrient="${ri}:${ii}:pt">${nutrientLabel(prescribedTotals([it]).pt)}</span> g <i aria-hidden="true">·</i> C <span data-food-nutrient="${ri}:${ii}:cb">${nutrientLabel(prescribedTotals([it]).cb)}</span> g <i aria-hidden="true">·</i> G <span data-food-nutrient="${ri}:${ii}:g">${nutrientLabel(prescribedTotals([it]).g)}</span> g</span></div>${it.measurement?measuredFoodControls(it,ri+':'+ii):`<label>Porções<input aria-label="Porções de ${esc(it.nome)}" data-food-q="${ri}:${ii}" type="number" min="0.1" step="0.1" max="1000" value="${esc(nutrientNumber(it.qtd)??'')}"></label>`}</div>${it.substituicoes?.length?`<div class="prescription-substitutions"><span>Substituições cadastradas</span>${it.substituicoes.map((x,ai)=>`<div class="substitution-row"><span><b>${esc(x.nome)}</b><small>${esc(portionLabel(x))}</small></span><div class="actions"><button class="btn small ghost" data-edit-alternative="${ri}:${ii}:${ai}" aria-label="Editar substituição ${esc(x.nome)}">Editar</button><button class="btn small ghost" data-remove-alternative="${ri}:${ii}:${ai}" aria-label="Remover substituição ${esc(x.nome)}">Remover</button></div></div>`).join('')}</div>`:''}<div class="prescription-food-tools"><div class="prescription-move-tools" role="group" aria-label="Ordem de ${esc(it.nome)}"><button class="btn small ghost prescription-icon-btn" data-move-food="${ri}:${ii}:-1" aria-label="Subir ${esc(it.nome)}" ${ii===0?'disabled':''}>${prescriptionIcon('up')}</button><button class="btn small ghost prescription-icon-btn" data-move-food="${ri}:${ii}:1" aria-label="Descer ${esc(it.nome)}" ${ii===r.itens.length-1?'disabled':''}>${prescriptionIcon('down')}</button></div><button class="btn small ghost" data-duplicate-food="${ri}:${ii}" aria-label="Duplicar alimento ${esc(it.nome)}">${prescriptionIcon('copy')}Duplicar</button><button class="btn ghost small prescription-alternative" data-alternative="${ri}:${ii}">${prescriptionIcon('swap')}Sugerir substituições</button></div></article>`).join('')||'<div class="prescription-meal-empty"><p>Comece pelos alimentos desta refeição.</p><span>As porções entram no resumo da prescrição.</span></div>'}</div>${P.recipeAssignment(ri,r)}<footer class="prescription-meal-footer"><button class="btn" data-add-food="${ri}">${prescriptionIcon('plus')}Alimento do catálogo</button><button class="btn small ghost danger" data-remove-meal="${ri}">Remover refeição</button></footer></div></section>`;
}
function editorView(){
 const p=patient(),data=S.edit;if(!data)return plansView();const day=validPlanDate(S.prescriptionDay)?S.prescriptionDay:today(),summary=planDaySummary(data,day),t=summary.totals,pub=published(p),anamnesis=latestAnamnesis(S.records,p.id),restrictions=[p.restrictions,anamnesis?.data?.allergies].filter(Boolean).filter((x,i,a)=>a.indexOf(x)===i);
 return `<div class="prescription-workspace"><header class="prescription-masthead"><button class="btn ghost prescription-back" data-page="plans">${prescriptionIcon('back')}Planos alimentares</button><div class="prescription-patient-heading"><span class="avatar">${initials(p.name)}</span><div><div class="eyebrow">Prescrição alimentar</div><h1>${esc(p.name)}</h1><p class="sub">${esc(p.goal||'Prepare o plano alimentar deste paciente.')}</p></div><span class="pill ${pub?'green':''}">${pub?'Publicado · v'+pub.version:'Sem publicação'}</span></div>${restrictions.length?`<p class="prescription-restriction"><b>Atenção ao prescrever</b><span>${restrictions.map(esc).join(' · ')}</span></p>`:''}</header><div class="prescription-commandbar"><div class="prescription-draft-state"><span class="prescription-status-dot" aria-hidden="true"></span><span data-draft-status>${S.localDirty?'Alterações por salvar':S.draftId?'Rascunho salvo':'Rascunho em edição'}</span></div><div class="prescription-main-actions"><button class="btn" data-action="save-draft">Salvar rascunho</button><button class="btn primary" data-action="publish-plan">${prescriptionIcon('check')}Revisar e publicar</button></div></div><div class="prescription-support"><details class="prescription-disclosure"><summary>Roteiro da consulta</summary><div class="prescription-support-content"><p class="sub">O atendimento e o plano são salvos separadamente.</p><div class="actions"><button class="btn small ghost" data-page="profile">1. Ficha do paciente</button><button class="btn small ghost" data-x="${anamnesis?'record-edit':'anamnesis'}" data-id="${esc(anamnesis?.id||'')}">2. Anamnese</button><button class="btn small ghost" data-follow-page="journal" data-follow-patient="${esc(p.id)}">3. Diário alimentar</button><button class="btn small ghost" data-page="assessments">4. Avaliações</button><span class="pill">5. Prescrição</span><button class="btn small" data-x="session">Registrar atendimento</button></div></div></details><details class="prescription-disclosure"><summary>Histórico e ferramentas</summary><div class="prescription-support-content actions"><button class="btn ghost small" data-action="discard-local">Reabrir versão salva</button><button class="btn small ghost" data-x="save-template">Salvar como modelo</button><button class="btn small ghost" data-x="plan-history">Histórico publicado</button></div></details></div><div class="prescription-layout"><aside class="prescription-sidebar" aria-label="Resumo e contexto da prescrição"><section class="prescription-summary"><div class="prescription-summary-heading"><h2>Resumo da prescrição</h2><span>Por dia da semana</span></div>${planDayControls(day,'prescription')}<div class="prescription-energy"><strong data-prescription-total="k">${nutrientLabel(t.k)}</strong><span>kcal</span></div><dl class="prescription-macros">${[['pt','Proteínas'],['cb','Carboidratos'],['g','Gorduras']].map(([key,label])=>`<div><dt>${label}</dt><dd><b data-prescription-total="${key}">${nutrientLabel(t[key])}</b> <span>g</span></dd></div>`).join('')}</dl><div data-prescription-day-note>${planDayNotice(summary)}</div><p class="prescription-catalog-note">Valores médios do catálogo: revise antes de publicar.</p></section>${editorContext()}<p class="prescription-publication-note">Salvar o rascunho mantém a versão atual no app do paciente. Para disponibilizar as mudanças, revise e publique.</p></aside><section class="prescription-setup"><label class="prescription-title-field">Título do plano<input id="plan-title" maxlength="160" value="${esc(data.titulo)}"></label><details class="prescription-settings"><summary>Vigência, água e orientações</summary><div class="prescription-settings-content"><div class="form-grid"><label>Válido a partir de<input id="plan-start" type="date" value="${esc(data.startOn||'')}"></label><label>Revisar até<input id="plan-end" type="date" value="${esc(data.endOn||'')}"></label></div><div class="form-grid"><label>Dias e contexto do plano<input id="plan-days" maxlength="300" value="${esc(data.dias||'Todos os dias')}" placeholder="Ex.: dias de trabalho"></label><label>Água prescrita (ml/dia)<input id="plan-water" type="number" min="250" max="10000" step="250" value="${data.aguaMl||2000}"></label></div><label>Orientações para o paciente<textarea id="plan-notes" maxlength="6000" placeholder="Orientações que acompanharão o plano no app do paciente">${esc(data.orientacoes)}</textarea></label></div></details></section><div class="prescription-meal-list"><div class="prescription-section-heading"><h2>Refeições do plano</h2><span>${data.refeicoes.length} ${data.refeicoes.length===1?'refeição':'refeições'}</span></div>${data.refeicoes.map((r,ri)=>editorMeal(r,ri,data.refeicoes.length)).join('')}<button class="btn prescription-add-meal" data-action="add-meal">${prescriptionIcon('plus')}Adicionar refeição</button></div></div></div>`;
}
function syncEditor(){if(!S.edit)return;S.edit.startOn=$('#plan-start')?.value??S.edit.startOn;S.edit.endOn=$('#plan-end')?.value??S.edit.endOn;S.edit.dias=$('#plan-days')?.value??S.edit.dias;S.edit.titulo=$('#plan-title')?.value??S.edit.titulo;S.edit.orientacoes=$('#plan-notes')?.value??S.edit.orientacoes;S.edit.aguaMl=Number($('#plan-water')?.value??S.edit.aguaMl);document.querySelectorAll('[data-meal-title]').forEach(e=>S.edit.refeicoes[+e.dataset.mealTitle].titulo=e.value);document.querySelectorAll('[data-meal-time]').forEach(e=>S.edit.refeicoes[+e.dataset.mealTime].hora=e.value);document.querySelectorAll('[data-food-q]').forEach(e=>{const [r,i]=e.dataset.foodQ.split(':').map(Number),item=S.edit.refeicoes[r].itens[i],next=e.value.trim()===''?null:Number(e.value);if(next!==nutrientNumber(item.qtd))item.qtd=next;});const dayInputs=[...document.querySelectorAll('[data-meal-day]')];if(dayInputs.length)S.edit.refeicoes.forEach((meal,ri)=>{meal.dias=dayInputs.filter(e=>e.checked&&Number(e.dataset.mealDay.split(':')[0])===ri).map(e=>Number(e.dataset.mealDay.split(':')[1]));});cacheEditor();updatePrescriptionSummary();const status=$('[data-draft-status]');if(status)status.textContent='Alterações por salvar';}
function updatePrescriptionSummary(){
 if(!S.edit)return;const summary=planDaySummary(S.edit,validPlanDate(S.prescriptionDay)?S.prescriptionDay:today()),totals=summary.totals;
 const note=$('[data-prescription-day-note]');if(note)note.innerHTML=planDayNotice(summary);
 document.querySelectorAll('[data-prescription-total]').forEach(e=>{e.textContent=nutrientLabel(totals[e.dataset.prescriptionTotal]);});
 document.querySelectorAll('[data-meal-total]').forEach(e=>{const meal=S.edit.refeicoes[Number(e.dataset.mealTotal)];if(meal)e.textContent=nutrientLabel(prescribedTotals(meal.itens).k);});
 document.querySelectorAll('[data-food-nutrient]').forEach(e=>{const [r,i,key]=e.dataset.foodNutrient.split(':'),item=S.edit.refeicoes[Number(r)]?.itens[Number(i)];if(item)e.textContent=nutrientLabel(prescribedTotals([item])[key]);});
}
function todayView(){const p=patient();if(!p)return '<div class="empty">Seu vínculo com o consultório ainda não está disponível.</div>';const pl=published()?.data,ll=logToday(),st=stats(p);let n=1;while(50*n*(n+1)<=st.xp)n++;const pct=Math.round(100*(st.xp-50*(n-1)*n)/(100*n));return heading('Meu acompanhamento',`Olá, ${esc(p.name.split(' ')[0])}.`,'Vamos cuidar da sua rotina, um dia de cada vez.')+`<div class="cols"><div><section class="card patient-hero"><div class="eyebrow">Sua jornada</div><div class="card-head" style="margin:18px 0"><h2>Nível ${n} · ${n>2?'No ritmo':n>1?'Aquecendo':'Iniciante'}</h2><span class="pill" style="border-color:#10131830">${st.xp} XP</span></div><div class="progress"><i style="width:${pct}%"></i></div><p class="sub">${50*n*(n+1)-st.xp} XP para o próximo nível</p><div class="week">${weekDays().map(([d,label])=>`<div class="day ${logs().some(x=>x.day===d&&x.followed)?'done':''}" style="${d===today()?'border-color:#101318':''}">${label}<b>${logs().some(x=>x.day===d&&x.followed)?'✓':Number(d.slice(8))}</b></div>`).join('')}</div><div class="card-head" style="margin-bottom:0"><span>${st.days} de ${S.clinic.weekly_goal} dias na meta semanal</span><button class="btn" data-action="followed">${ll.followed?'✓ Plano seguido hoje':'Segui meu plano hoje'}</button></div></section><section class="card"><div class="card-head"><h2>Refeições de hoje</h2><span class="pill">${(ll.meals||[]).length}/${pl?.refeicoes?.length||0} registradas</span></div>${pl?mealsView(pl,true):'<div class="empty">Sua nutricionista está preparando o plano alimentar. Ele aparecerá aqui depois da publicação.</div>'}</section></div><div><section class="card"><div class="card-head"><h2>Água de hoje</h2><span class="activity-icon">◈</span></div><div class="water"><div class="big-number">${((ll.water_ml||0)/1000).toLocaleString('pt-BR')}<span style="font-size:18px"> L</span></div><span class="sub">de ${(pl?.aguaMl||2000)/1000} L</span></div><div class="progress"><i style="width:${Math.min(100,(ll.water_ml||0)/(pl?.aguaMl||2000)*100)}%"></i></div><div class="actions"><button class="btn primary" data-action="water">+ 250 ml</button><button class="btn ghost small" data-action="water-undo" aria-label="Remover 250 ml de água">− 250 ml</button></div></section><section class="card"><div class="card-head"><h2>Como você está?</h2><span class="pill purple">Check-in</span></div><p class="sub">Compartilhe seu sono, disposição e dificuldades com a sua nutri.</p>${ll.mood?`<p>${esc(moodName(ll.mood))} · Sono: ${esc(ll.sleep!=null?ll.sleep+' h':'Não informado')}</p>`:''}<button class="btn" data-action="checkin">${ll.mood?'Atualizar check-in':'Responder check-in'}</button></section><section class="card journey"><div class="eyebrow">Próxima conquista</div><h2>Seu esforço conta.</h2><p class="sub">Registre sua rotina e acompanhe suas medalhas evolutivas.</p><button class="btn small" data-page="achievements">Ver minhas conquistas</button></section></div></div>`;}
function weekDays(){const d=new Date();d.setDate(d.getDate()-((d.getDay()+6)%7));return ['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map((n,i)=>{let x=new Date(d);x.setDate(x.getDate()+i);return [localDay(x),n];});}
function mealsView(pl,buttons=false){const done=mealPresence({patientId:patient()?.id,day:today(),logs:S.logs,records:S.records,planVersion:published()?.version}).mealIds;return pl.refeicoes.map(r=>{const t=MT_NUTRICAO.totalItens(r.itens),recipe=(pl.receitas||[]).find(x=>x.id===r.receitaId);return `<div class="meal"><div class="meal-head"><div><span class="eyebrow">${esc(r.hora)}</span><h3 style="margin:7px 0">${esc(r.titulo)}</h3><p class="sub">${esc(mealDaysLabel(r.dias))}</p></div>${buttons?`<button class="btn small ${done.includes(r.id)?'ghost':'primary'}" data-log-meal="${esc(r.id)}" aria-label="${done.includes(r.id)?'Ver registro de':'Registrar'} ${esc(r.titulo)}">${done.includes(r.id)?'✓ Ver registro':'Registrar'}</button>`:`<span class="pill">${nutrientLabel(t.k)} kcal</span>`}</div>${r.itens.map(it=>`<div class="summary-line"><span>${esc(it.nome)}</span><span>${esc(portionLabel(it))}</span></div>${it.substituicoes?.length?`<p class="sub">Pode substituir por: ${it.substituicoes.map(x=>`${esc(x.nome)} (${esc(portionLabel(x))})`).join(' ou ')}</p>`:''}`).join('')}<div class="actions">${!buttons?`<button class="btn small" data-log-meal="${esc(r.id)}">${done.includes(r.id)?'Ver registro de hoje':'Registrar refeição'}</button>`:''}${recipe?`<button class="btn small ghost" data-x="plan-recipe" data-id="${esc(r.id)}">Ver preparo · ${esc(recipe.nome||recipe.n||'Receita do plano')}</button>`:''}</div></div>`;}).join('');}
function foodView(){const pl=published()?.data;if(!pl)return heading('Prescrição','Meu plano alimentar','')+'<div class="empty">Seu plano ainda não foi publicado.</div>';const t=MT_NUTRICAO.totalPlano(pl);return heading('Minha prescrição',esc(pl.titulo),`Por ${esc(pl.responsavel||S.clinic.professional_name)} · ${esc(pl.crn||S.clinic.crn)}`,'<button class="btn" data-action="print">Imprimir plano</button>')+`<div class="cols"><section class="card">${mealsView(pl)}</section><div><section class="card"><h2>Orientações da nutri</h2><p class="sub">${esc(pl.dias||'Todos os dias')}${pl.startOn?' · início '+dateLabel(pl.startOn):''}${pl.endOn?' · revisão '+dateLabel(pl.endOn):''}</p><button class="btn small ghost" data-x="plan-history">Ver planos anteriores</button><p class="sub" style="white-space:pre-wrap">${esc(pl.orientacoes||'Converse com sua nutricionista sobre os ajustes da sua rotina.')}</p><div class="macro-bar"><div><b>${Math.round(t.pt)} g</b><span>Proteínas</span></div><div><b>${Math.round(t.cb)} g</b><span>Carboidratos</span></div><div><b>${Math.round(t.g)} g</b><span>Gorduras</span></div></div><span class="pill">Versão ${published().version}</span></section><section class="card"><h2>Lista de compras</h2>${shopping(pl).map(x=>`<div class="summary-line"><span>${esc(x.nome)}</span><span>${esc(portionLabel(x))}</span></div>`).join('')}</section></div></div>`;}
function shopping(pl){const a=new Map();for(const r of pl.refeicoes)for(const it of r.itens){const k=it.nome+it.porcao;if(a.has(k))a.get(k).qtd+=it.qtd;else a.set(k,{...it});}return [...a.values()];}
function metrics(p=patient()){const ll=logs(p),n={registros:{}},habitos={},peso={},qa={};for(const x of ll){for(const id of x.meals||[])n.registros[x.day+'-'+id]={d:x.day};habitos[x.day]={0:x.water_ml>0,1:x.followed,2:x.sleep!=null};if(x.weight)peso[x.day]=x.weight;if(x.mood)qa[x.day]=x.day;}for(const x of S.records.filter(x=>x.patient_id===p?.id&&x.kind==='food_journal'&&x.visibility==='patient'&&!x.data?.archived&&x.data?.day<=today()))n.registros[x.data.day+'-'+(x.data.mealId||x.id)]={d:x.data.day};return MT_MEDALHAS.metricas({hoje:today(),nutricao:n,habitos,peso,qa});}
function badgeDefs(){return MT_MEDALHAS.catalogo.filter(x=>['nutri-dias','nutri-registros','nutri-semana','habito-agua','habito-sono','acompanhamento-checkins'].includes(x.id));}
function achievementsView(){const m=metrics();return heading('Minha jornada','Conquistas que crescem com você','Constância, registros e cuidado. Cada pequeno passo conta.')+`<div class="badge-grid">${badgeDefs().map(d=>{const p=MT_MEDALHAS.progresso(d,m);return `<section class="badge ${p.nivel===0?'locked':''}"><div class="medal" aria-hidden="true">${{'gota':'◈','maca':'♧','prato':'◎','calendario':'▦','lua':'☾','check':'✓'}[d.icone]||'✦'}</div><h3>${esc(d.n)}</h3><p>${esc(d.criterio)}</p><span class="pill ${p.nivel?'green':''}">${p.nivel?'Medalha nível '+p.nivel:'Primeiro marco'}</span><div class="progress"><i style="width:${p.percentual}%"></i></div><p>${p.valor} / ${p.proxima??p.atual} ${esc(d.unidade)}</p></section>`;}).join('')}</div><section class="card" style="margin-top:22px"><h2>Desafios do consultório</h2>${S.challenges.map(c=>{const value=m[c.metric]||0;return `<div class="patient-row"><span class="activity-icon">◇</span><div class="grow"><b>${esc(c.title)}</b><div class="progress"><i style="width:${Math.min(100,value/c.target*100)}%"></i></div></div><span class="pill green">${value}/${c.target}</span></div>`;}).join('')||'<p class="sub">Sua nutri ainda não criou desafios.</p>'}</section><p class="sub">A partir de 09/10/2026: cuidado no dia +10 XP, check-in +5, registro alimentar +5, até 20 XP por dia. Pesagens não geram pontos novos. O histórico anterior é preservado.</p>`;}
function progressView(){const ll=logs().slice().sort((a,b)=>a.day.localeCompare(b.day)),weights=ll.filter(x=>x.weight);return heading('Meu acompanhamento','Minha evolução','Seu histórico ajuda a ajustar o cuidado à sua rotina.','<button class="btn primary" data-action="checkin">Registrar check-in</button>')+`<div class="cols"><div><section class="card"><h2>Minha rotina nos últimos dias</h2><div class="week">${weekDays().map(([d,n])=>`<div class="day ${ll.some(x=>x.day===d&&x.followed)?'done':''}">${n}<b>${ll.some(x=>x.day===d&&x.followed)?'✓':'·'}</b></div>`).join('')}</div><div class="summary-line"><span>Dias de diário</span><b>${metrics().nutriDias}</b></div><div class="summary-line"><span>Check-ins respondidos</span><b>${metrics().checkins}</b></div><div class="summary-line"><span>Refeições registradas</span><b>${metrics().nutriRegistros}</b></div></section><section class="card"><h2>Registros de peso</h2><p class="sub">Opcional. Avalie os registros com a sua nutricionista.</p>${weights.map(x=>`<div class="summary-line"><span>${dateLabel(x.day)}</span><b>${x.weight} kg</b></div>`).join('')||'<div class="empty">Nenhum peso registrado.</div>'}</section></div><section class="card"><h2>Meu histórico</h2>${ll.slice(-14).reverse().map(x=>`<div class="activity"><span class="activity-icon">✓</span><div><p>${dateLabel(x.day)} · ${x.water_ml||0} ml de água</p><small>${(x.meals||[]).length} refeições${x.followed?' · Plano acompanhado':''}</small>${x.note?`<p class="sub">${esc(x.note)}</p>`:''}</div></div>`).join('')||'<div class="empty">Os seus registros aparecerão aqui.</div>'}</section></div>`;}
function chatView(){const p=patient();if(!p)return '<div class="empty">Nenhum paciente vinculado.</div>';return heading('Acompanhamento',S.role==='nutri'?esc(p.name):'Converse com sua nutri',S.role==='nutri'?'Escute a rotina e acompanhe as dúvidas.':esc(S.clinic.professional_name))+ (S.role==='nutri'?`<label>Conversa com<select id="chat-patient">${S.patients.map(x=>`<option value="${x.id}" ${x.id===S.selected?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`:'')+`<section class="card"><div class="chatbox" id="chatbox">${S.messages.filter(x=>x.patient_id===p.id).map(x=>`<div class="message ${x.sender_id===(S.demo?(S.role==='nutri'?'demo':'patient-demo'):S.user?.id)?'mine':''}">${esc(x.body)}<small>${x.sender_id===(p.clinician_id||'demo')?'Nutricionista':'Paciente'} · ${new Date(x.created_at).toLocaleString('pt-BR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</small></div>`).join('')||'<div class="empty">Comece a conversa por aqui.</div>'}</div><form id="message-form"><label>Mensagem<textarea id="message-body" maxlength="4000" required placeholder="Escreva sua mensagem"></textarea></label><button class="btn primary" type="submit">Enviar mensagem</button></form></section>`;}
function appointmentsView(){return heading('Consultório','Agenda de consultas','Organize os próximos encontros.','<button class="btn primary" data-action="new-appointment">+ Agendar consulta</button>')+`<section class="card">${S.appointments.slice().sort((a,b)=>a.start_at.localeCompare(b.start_at)).map(x=>`<div class="patient-row"><span class="activity-icon">▦</span><div class="grow"><b>${esc(S.patients.find(p=>p.id===x.patient_id)?.name||'Paciente')}</b><small>${esc(x.note)}</small></div><span>${new Date(x.start_at).toLocaleString('pt-BR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</span><button class="btn small ghost danger" data-cancel-appointment="${x.id}">Cancelar</button></div>`).join('')||'<div class="empty">Nenhuma consulta agendada.</div>'}</section>`;}
function challengesView(){return heading('Engajamento','Gamificação do consultório','Recompense o acompanhamento de hábitos e a consistência.','<button class="btn primary" data-action="new-challenge">+ Novo desafio</button>')+`<div class="cols"><section class="card"><div class="card-head"><h2>Desafios personalizados</h2><span class="pill green">${S.challenges.length} ativos</span></div>${S.challenges.map(c=>`<div class="patient-row"><span class="activity-icon">◇</span><div class="grow"><b>${esc(c.title)}</b><small>Meta: ${c.target} ${metricName(c.metric)}</small></div><button class="btn small ghost danger" data-delete-challenge="${c.id}">Remover</button></div>`).join('')||'<div class="empty">Crie um desafio para aparecer no app dos seus pacientes.</div>'}<div class="notice">As medalhas evoluem pelos registros confirmados. Cada refeição conta uma vez por dia. Os pontos novos reconhecem o cuidado, com limite de 20 XP por dia; pesagens não geram bônus.</div></section><section class="card"><h2>Meta semanal</h2><form id="weekly-form" style="margin-top:20px"><label>Dias por semana<input id="weekly-goal" type="number" min="1" max="7" value="${S.clinic.weekly_goal}" required></label><button class="btn primary">Salvar meta</button></form><p class="sub">A meta aparece na jornada do paciente e ajuda a acompanhar a rotina.</p></section></div><h2 style="margin-bottom:20px">Medalhas da jornada</h2><div class="badge-grid">${badgeDefs().map(d=>`<div class="badge"><div class="medal">✦</div><h3>${esc(d.n)}</h3><p>${esc(d.criterio)}</p><span class="pill">Marcos: ${d.metas.join(' · ')}</span></div>`).join('')}</div>`;}
function metricName(m){return ({nutriDias:'dias de diário',nutriRegistros:'refeições registradas',habitosAgua:'dias com água',habitosSono:'dias com registro de sono',checkins:'check-ins'})[m]||'registros';}
function brandView(){return heading('Seu jeito de cuidar','Identidade do consultório','A mesma marca acompanha o nutricionista e o paciente.')+`<div class="cols"><section class="card"><form id="brand-form"><div class="form-grid"><label>Nome da clínica<input id="brand-name" maxlength="120" required value="${esc(S.clinic.name)}"></label><label>Nome do profissional<input id="brand-prof" maxlength="120" required value="${esc(S.clinic.professional_name)}"></label></div><div class="form-grid"><label>CRN<input id="brand-crn" maxlength="80" value="${esc(S.clinic.crn)}"></label><label>Cor da marca<input id="brand-color" type="color" value="${S.clinic.color}"></label></div><label>Logo da clínica (PNG, JPG ou WebP; até 200 KB)<input id="brand-logo" type="file" accept="image/png,image/jpeg,image/webp"></label><div class="actions"><button class="btn primary" type="submit">Salvar personalização</button><button class="btn ghost" type="button" id="remove-logo">Remover logo</button></div></form></section><section class="card journey"><div class="eyebrow">No app do paciente</div>${S.clinic.logo?`<img class="logo" src="${esc(S.clinic.logo)}" alt="Logo da clínica">`:''}<h2>${esc(S.clinic.name)}</h2><p class="sub">${esc(S.clinic.professional_name)}<br>${esc(S.clinic.crn)}</p><span class="pill green">Identidade personalizada</span><p class="sub">A cor e a marca aparecem no plano, nos hábitos e na jornada de conquistas.</p><button class="btn small ghost" data-action="theme">Alternar tema claro/escuro</button></section></div>`;}
const cfg=window.TORQUE_NUTRI_CONFIG||{};
const authStorageKey=cfg.supabaseUrl?'sb-'+new URL(cfg.supabaseUrl).hostname.split('.')[0]+'-auth-token':'';
let authStorage=null,authSubscription=null,authStorageBlocked=false;
const pendingCleanupUsers=new Set();
function createAuthClient(){
 if(demoRole||!cfg.supabaseUrl||!cfg.publishableKey)return null;
 let readable=true,writable=true;
 const storage={getItem:key=>readable?localStorage.getItem(key):null,setItem:(key,value)=>{if(writable)localStorage.setItem(key,value);},removeItem:key=>{if(readable)localStorage.removeItem(key);}};
 authStorage={suspend:()=>{writable=false;},retire:()=>{readable=false;writable=false;}};
 return supabase.createClient(cfg.supabaseUrl,cfg.publishableKey,{auth:{storageKey:authStorageKey,storage}});
}
let db=createAuthClient();
const reminders=createReminderController({state:()=>S,database:()=>db});
const P=createPlatform({state:()=>S,database:()=>db,reminders,sessionEpoch:()=>loadSequence,esc,uid,today,dateLabel,heading,modal,toast,render,run,errorCheck,allRows,basicProfile:profileView,published,stats,saveLog,loadData,openEditor,cacheEditor,action,syncQueue,queueCount,cacheSnapshot,syncEditor,printPlan,logs,metrics,badgeDefs,mealsView,moodName,brandView,progressView});
navNutri=P.pages;
const patientColumns='id,clinic_id,clinician_id,user_id,name,email,goal,restrictions,created_at,updated_at';
const authParams=new URLSearchParams(demoRole?'':location.search);
let pendingReminderPage=['booking','forms'].includes(authParams.get('reminder'))?authParams.get('reminder'):'';
function applyReminderRoute(){if(!pendingReminderPage||S.demo||!S.user||S.loading||!S.patients.length||['auth','join','invite'].includes(S.page))return;if(S.role==='patient')S.page=pendingReminderPage;pendingReminderPage='';removeAuthParam('reminder');}
const recoveryRequested=authParams.has('recuperar');
let authMode=recoveryRequested?'recovery':'login',authRole=authParams.get('perfil')==='patient'?'patient':'nutri';
let recoveryUserId=null,authNotice='';
if(!demoRole&&(authParams.has('error')||new URLSearchParams(location.hash.slice(1)).has('error')))authNotice='O link de acesso é inválido ou expirou. Solicite um novo link de recuperação ou confirmação.';
let pendingInvite=demoRole?'':(authParams.get('convite')||sessionStorage.getItem('torque-nutri-invite')||'');
if(pendingInvite){sessionStorage.setItem('torque-nutri-invite',pendingInvite);authRole='patient';}
function confirmationRedirect(){const url=new URL(appBase.href);url.searchParams.set('entrar','1');url.searchParams.set('perfil',authRole);if(pendingInvite)url.searchParams.set('convite',pendingInvite);return url.href;}
function removeAuthParam(name){const url=new URL(location.href);url.searchParams.delete(name);for(const key of ['error','error_description','error_code'])url.searchParams.delete(key);if(name==='recuperar'){url.searchParams.delete('code');if(url.searchParams.get('type')==='recovery')url.searchParams.delete('type');}const fragment=new URLSearchParams(url.hash.slice(1));if(['access_token','refresh_token','token_type','expires_in','expires_at','error','error_description','error_code'].some(key=>fragment.has(key))||fragment.get('type')==='recovery')url.hash='';history.replaceState({},'',url.pathname+url.search+url.hash);}
function resetAccountState(clearLocal=true){
 reminders.clearDevice().catch(()=>toast('Não foi possível desligar todas as notificações deste aparelho. Revogue a permissão no navegador.'));
 ++loadSequence;S.loading=false;S.loadError='';S.financeLedger={available:false};
 let cleanupError=null;if(clearLocal&&S.user?.id)pendingCleanupUsers.add(S.user.id);
 if(clearLocal)for(const userId of pendingCleanupUsers){let userError=null;try{localStorage.removeItem('torque-nutri-cache:'+userId);}catch(e){userError=e;}try{for(let i=sessionStorage.length-1;i>=0;i--){const key=sessionStorage.key(i);if(key?.startsWith('torque-nutri-')&&key.includes(userId))sessionStorage.removeItem(key);}}catch(e){userError=userError||e;}if(userError)cleanupError=cleanupError||userError;else pendingCleanupUsers.delete(userId);}
 recoveryUserId=null;
 Object.assign(S,{user:null,demo:false,role:'nutri',clinic:{...demoClinic},selected:null,edit:null,draftId:null,expectedVersion:null,localDirty:false,offline:false,patients:[],plans:[],logs:[],messages:[],appointments:[],challenges:[],resources:[],records:[],finances:[],posts:[],interactions:[],page:'auth'});
 $('#modal').close();return cleanupError;
}
async function logoutAccount(){
 const previous=db;let remoteError=null,cleanupError=null;
 try{await reminders.clearDevice();}catch(error){remoteError=error;}
 authStorage?.suspend();authSubscription?.unsubscribe();authSubscription=null;
 if(previous){try{await previous.auth.stopAutoRefresh();const result=await previous.auth.signOut({scope:'local'});remoteError=remoteError||result.error;}catch(e){remoteError=e;}}
 // Retired storage cannot restore a session or erase a later session after an in-flight refresh.
 authStorage?.retire();
 try{for(const key of [authStorageKey,authStorageKey+'-user',authStorageKey+'-code-verifier'])if(authStorageKey)localStorage.removeItem(key);}catch(e){cleanupError=e;}
 cleanupError=resetAccountState()||cleanupError;authMode='login';authRole=pendingInvite?'patient':'nutri';
 removeAuthParam('recuperar');
 authStorageBlocked=!!cleanupError;db=cleanupError?null:createAuthClient();if(db)watchAuth();
 authNotice=cleanupError?'Não foi possível apagar a sessão salva neste aparelho. A saída local não está garantida; tente limpar novamente.':remoteError?'Você saiu deste aparelho. A revogação desta sessão no servidor não foi confirmada.':'';
 render();if(cleanupError)throw Error(authNotice);toast(remoteError?authNotice:'Você saiu deste aparelho.');
}
function watchAuth(){authSubscription=db.auth.onAuthStateChange((event,session)=>{
 if(event==='SIGNED_OUT'&&S.user){const error=resetAccountState();authMode='login';authStorageBlocked=!!error;authNotice=error?'Não foi possível apagar todos os dados locais desta conta. Tente limpar novamente.':'';removeAuthParam('recuperar');render();}
 if(event==='SIGNED_IN'&&S.user&&session?.user.id!==S.user.id){const error=resetAccountState();authMode='login';authStorageBlocked=!!error;authNotice=error?'Não foi possível apagar todos os dados locais desta conta. Tente limpar novamente.':'';render();return reminders.clearDevice().catch(()=>{}).finally(()=>location.reload());}
 if(event==='PASSWORD_RECOVERY'&&session?.user){resetAccountState(!!S.user&&S.user.id!==session.user.id);recoveryUserId=session.user.id;S.user=session.user;S.demo=false;authNotice='';authMode='password';S.page='auth';render();}
 }).data.subscription;}
async function allRows(makeQuery){const rows=[];for(let offset=0;;offset+=500){const page=errorCheck(await makeQuery().range(offset,offset+499));rows.push(...page);if(page.length<500)return rows;}}
function errorCheck(r){if(r.error)throw Error(r.error.message);return r.data;}
async function loadData(){
 if(!db||!S.user)return;
 const sequence=++loadSequence,userId=S.user.id,client=db;
 const current=()=>S.user?.id===userId&&db===client&&sequence===loadSequence;
 const checkCurrent=()=>{if(!current())throw Error('A sessão ou a leitura mudou. Atualize para continuar.');};
 S.loading=true;S.loadError='';
 try{
 const own=errorCheck(await client.from('clinics').select('*').eq('owner_id',userId).maybeSingle());
 checkCurrent();
 const role=own?'nutri':'patient';let patients=own?await allRows(()=>client.from('patients').select(patientColumns).eq('clinician_id',userId).eq('clinic_id',own.id).order('name').order('id')):errorCheck(await client.from('patients').select(patientColumns).eq('user_id',userId).order('id'));
 checkCurrent();
 if(!own&&!patients.length){
  const currentUser=S.user;
  // A revocation already observed online must not reopen from an older offline snapshot.
  // Overwrite first so a failed removal cannot leave the clinical snapshot usable.
  try{localStorage.setItem('torque-nutri-cache:'+userId,JSON.stringify({userId,accessRevoked:true}));}catch{}
  const cleanupError=resetAccountState();S.user=currentUser;S.role='patient';
  authStorageBlocked=!!cleanupError;authNotice=cleanupError?'Seu vínculo não está disponível. Não foi possível apagar todos os dados locais desta conta. Tente limpar novamente.':'';
  if(cleanupError){authMode='login';throw Error(authNotice);}
  S.page='join';return;
 }
 const clinicId=own?.id||(patients.some(p=>p.clinic_id===S.clinic.id)?S.clinic.id:patients[0].clinic_id);
 const clinic=own||errorCheck(await client.from('clinics').select('*').eq('id',clinicId).single());
 checkCurrent();
 patients=patients.filter(p=>p.clinic_id===clinic.id);
 const patientIds=patients.map(p=>p.id);
 const [plans,daily,messages,appointments,challenges]=await Promise.all([
 patients.length?allRows(()=>client.from('plans').select('*').in('patient_id',patientIds).order('id')):[],
 patients.length?allRows(()=>client.from('daily_logs').select('*').in('patient_id',patientIds).order('day').order('id')):[],
 patients.length?allRows(()=>client.from('messages').select('*').in('patient_id',patientIds).order('created_at').order('id')):[],
 patients.length?allRows(()=>client.from('appointments').select('*').in('patient_id',patientIds).order('start_at').order('id')):[],
 allRows(()=>client.from('challenges').select('*').eq('clinic_id',clinic.id).order('id'))]);
 checkCurrent();
 const platform=await P.load({context:{userId,clinic,patients,role},defer:true});
 checkCurrent();
 const retainEditor=S.clinic.id===clinic.id&&patientIds.includes(S.selected);
 Object.assign(S,{demo:false,role,clinic,patients,plans,logs:daily,messages,appointments,challenges,...platform,offline:false,loadError:''});
 if(!retainEditor){S.edit=null;S.draftId=null;S.expectedVersion=null;S.localDirty=false;if(S.page==='editor')S.page=role==='nutri'?'patients':'today';}
 if(!patients.some(p=>p.id===S.selected))S.selected=patients[0]?.id||null;
 await reminders.setContext().catch(()=>{});checkCurrent();
 cacheSnapshot();
 }catch(error){if(current())S.loadError='Não foi possível atualizar todos os dados. A última leitura completa foi preservada.';throw error;}
 finally{if(current())S.loading=false;}
}

function authView(){$('#app').innerHTML=`<section class="auth card"><div class="wordmark"><span class="mark">T</span>torque<span> nutri</span></div><h1>${authMode==='signup'?'Crie seu acesso.':authMode==='recovery'?'Recupere seu acesso.':authMode==='password'?'Escolha uma nova senha.':'Seu cuidado, conectado.'}</h1><p class="sub">${authRole==='patient'?'Entre com o e-mail cadastrado pela sua nutricionista.':'Seu consultório e seus pacientes em um só lugar.'}</p>${authNotice?'<div class="notice warning" role="status">'+esc(authNotice)+'</div>':''}${!db&&!authStorageBlocked?'<div class="notice warning">O banco está sendo preparado. A demonstração está disponível enquanto isso.</div>':''}${authMode==='login'||authMode==='signup'?`<div class="tabs"><button class="btn ${authRole==='nutri'?'primary':''}" id="auth-nutri">Sou nutricionista</button><button class="btn ${authRole==='patient'?'primary':''}" id="auth-patient">Sou paciente</button></div>`:''}<form id="auth-form">${authMode==='signup'&&authRole==='nutri'?'<label>Nome profissional<input id="auth-name" autocomplete="name" maxlength="120" required></label><label>Nome do consultório<input id="auth-clinic" maxlength="120" required></label>':''}${authMode!=='password'?'<label>E-mail<input id="auth-email" type="email" autocomplete="email" required maxlength="320"></label>':''}${authMode!=='recovery'?'<label>Senha<input id="auth-password" type="password" minlength="8" required autocomplete="'+(authMode==='login'?'current-password':'new-password')+'"></label>':''}<button class="btn primary" type="submit" ${!db||authStorageBlocked?'disabled':''}>${authMode==='signup'?'Criar conta':authMode==='recovery'?'Receber recuperação':authMode==='password'?'Salvar nova senha':'Entrar'}</button><p id="auth-result" class="sub" role="status"></p></form><div class="actions" style="margin-top:18px"><button class="btn ghost small" id="auth-toggle">${authMode==='login'?'Criar uma conta':'Já tenho conta'}</button>${authMode==='login'?'<button class="btn ghost small" id="auth-recovery">Esqueci a senha</button>':''}</div>${authStorageBlocked?'<button class="btn" id="auth-retry-logout">Tentar limpar sessão salva</button>':''}<button class="btn small ghost" style="margin-top:18px" id="back-demo">Explorar demonstração</button>${ecosystemLink()}</section>`;$('#auth-nutri')&&( $('#auth-nutri').onclick=()=>{authRole='nutri';authView();});$('#auth-patient')&&($('#auth-patient').onclick=()=>{authRole='patient';authView();});$('#auth-toggle').onclick=()=>{authMode=authMode==='login'?'signup':'login';authView();};$('#auth-recovery')&&($('#auth-recovery').onclick=()=>{authMode='recovery';authView();});$('#auth-retry-logout')&&($('#auth-retry-logout').onclick=()=>run(logoutAccount));$('#back-demo').onclick=()=>{location.assign(new URL(authRole==='patient'?'demo-paciente.html':'demo-nutricionista.html',appBase).href);};$('#auth-form').onsubmit=e=>{e.preventDefault();run(authSubmit);};}
async function authSubmit(){if(!db||authStorageBlocked)throw Error(authNotice||'O acesso ainda não está disponível.');const btn=$('#auth-form button[type=submit]');btn.disabled=true;const email=$('#auth-email')?.value.trim().toLowerCase(),password=$('#auth-password')?.value;try{if(authMode==='recovery'){const redirect=new URL(confirmationRedirect());redirect.searchParams.delete('entrar');redirect.searchParams.set('recuperar','1');errorCheck(await db.auth.resetPasswordForEmail(email,{redirectTo:redirect.href}));$('#auth-result').textContent='Se houver uma conta com esse e-mail, você receberá o link de recuperação.';return;}if(authMode==='password'){if(!recoveryUserId)throw Error('Abra um link de recuperação válido para escolher uma nova senha.');const current=errorCheck(await db.auth.getUser());if(current.user?.id!==recoveryUserId||S.user?.id!==recoveryUserId)throw Error('A sessão de recuperação mudou. Solicite um novo link.');errorCheck(await db.auth.updateUser({password}));recoveryUserId=null;removeAuthParam('recuperar');authNotice='';toast('Nova senha salva.');authMode='login';S.page='auth';render();return;}if(authMode==='signup'){const name=$('#auth-name')?.value.trim(),clinic=$('#auth-clinic')?.value.trim();const r=await db.auth.signUp({email,password,options:{emailRedirectTo:confirmationRedirect(),data:{display_name:name||'',clinic_name:clinic||''}}});errorCheck(r);if(!r.data.session){$('#auth-result').textContent='Confirme seu e-mail e depois entre na conta. Ao entrar, você poderá configurar o consultório ou resgatar seu convite.';return;}S.user=r.data.user;if(authRole==='nutri')await createClinic(clinic,name);}else{const r=await db.auth.signInWithPassword({email,password});errorCheck(r);S.user=r.data.user;}if(pendingInvite){S.demo=false;S.page='invite';render();return;}await loadData();if(queueCount()&&navigator.onLine)await syncQueue();if(S.page==='join'&&authRole==='nutri'){clinicSetup();return;}S.page=S.page==='join'?'join':S.role==='nutri'?'overview':'today';render();}catch(e){$('#auth-result')&&($('#auth-result').textContent=e.message);throw e;}finally{if(btn.isConnected)btn.disabled=false;}}
async function createClinic(name,professional){errorCheck(await db.from('clinics').insert({owner_id:S.user.id,name,professional_name:professional,color:'#5de0b4',weekly_goal:5}));}
function clearPendingInvite(){pendingInvite='';sessionStorage.removeItem('torque-nutri-invite');removeAuthParam('convite');}
function inviteSessionView(){
 $('#app').innerHTML=`<section class="auth card"><div class="wordmark">torque<span> nutri</span></div><h1>Você recebeu um convite.</h1><p class="sub">Conta conectada: <b>${esc(S.user?.email||'E-mail não disponível')}</b>.</p><p class="sub">Resgate apenas se esta for a conta com o mesmo e-mail cadastrado pela nutricionista. Você também pode trocar de conta ou continuar sem resgatar o convite.</p><div class="actions"><button class="btn primary" id="invite-redeem">Resgatar com esta conta</button><button class="btn" id="invite-switch">Trocar conta</button><button class="btn ghost" id="invite-continue">Continuar sem resgatar</button></div></section>`;
 $('#invite-redeem').onclick=()=>run(async()=>{if(!pendingInvite)throw Error('O convite não está disponível.');errorCheck(await db.rpc('redeem_patient_invite',{p_code:pendingInvite}));clearPendingInvite();await loadData();S.page=S.role==='nutri'?'overview':'today';render();toast('Convite resgatado.');});
 $('#invite-switch').onclick=()=>run(logoutAccount);
 $('#invite-continue').onclick=()=>run(async()=>{clearPendingInvite();await loadData();S.page=S.page==='join'?'join':S.role==='nutri'?'overview':'today';render();});
 if(S.busy)lockUI();
}
function clinicSetup(){$('#app').innerHTML=`<section class="auth card"><div class="wordmark">torque<span> nutri</span></div><h1>Configure seu consultório.</h1><form id="setup-form"><label>Nome da clínica<input id="setup-clinic" required maxlength="120" value="${esc(S.user?.user_metadata?.clinic_name)}"></label><label>Nome profissional<input id="setup-prof" required maxlength="120" value="${esc(S.user?.user_metadata?.display_name)}"></label><button class="btn primary">Criar meu consultório</button></form></section>`;$('#setup-form').onsubmit=e=>{e.preventDefault();run(async()=>{await createClinic($('#setup-clinic').value.trim(),$('#setup-prof').value.trim());await loadData();S.page='overview';render();});};}
function joinView(){$('#app').innerHTML=`<section class="auth card"><div class="wordmark">torque<span> nutri</span></div><h1>Conecte-se à sua nutri.</h1><p class="sub">Use o código de convite enviado pelo consultório. Sua conta precisa usar o mesmo e-mail do cadastro e estar confirmada.</p><form id="join-form"><label>Código do convite<input id="invite-code" required minlength="64" maxlength="64" value="${esc(pendingInvite)}" autocomplete="off"></label><button class="btn primary">Conectar acompanhamento</button></form><div class="actions" style="margin-top:16px"><button class="btn ghost small" id="join-clinic">Sou nutricionista: configurar consultório</button><button class="btn ghost small" id="join-logout">Sair</button></div></section>`;$('#join-form').onsubmit=e=>{e.preventDefault();run(async()=>{errorCheck(await db.rpc('redeem_patient_invite',{p_code:$('#invite-code').value.trim()}));pendingInvite='';sessionStorage.removeItem('torque-nutri-invite');history.replaceState({},'',location.pathname);await loadData();S.page='today';render();toast('Você está conectado à sua nutricionista.');});};$('#join-clinic').onclick=()=>clinicSetup();$('#join-logout').onclick=()=>run(()=>action('logout'));}
function modal(title,body,submit){$('#modal-body').innerHTML=`<div class="card-head"><h2>${title}</h2><button class="btn ghost small" id="close-modal" aria-label="Fechar janela">×</button></div><div id="modal-feedback" class="notice" role="alert" hidden></div>${submit?'<form id="modal-form">':''}${body}${submit?'<div class="actions" style="margin-top:22px"><button class="btn primary" type="submit">Salvar</button><button class="btn ghost" type="button" id="cancel-modal">Cancelar</button></div></form>':''}`;$('#close-modal').onclick=()=>$('#modal').close();$('#cancel-modal')&&($('#cancel-modal').onclick=()=>$('#modal').close());if(submit)$('#modal-form').onsubmit=e=>{e.preventDefault();run(async()=>{const b=$('#modal-form button[type=submit]');b.disabled=true;try{await submit();$('#modal').close();}finally{if(b.isConnected)b.disabled=false;}});};if(!$('#modal').open)$('#modal').showModal();}
function newPatient(existing){const p=existing||{};modal(existing?'Editar paciente':'Novo paciente',`<label>Nome completo<input id="p-name" required maxlength="120" value="${esc(p.name)}"></label><label>E-mail para acesso ao app<input id="p-email" type="email" required maxlength="320" value="${esc(p.email)}"></label><label>Objetivo do acompanhamento<input id="p-goal" maxlength="2000" value="${esc(p.goal)}"></label><label>Restrições, preferências e alergias<textarea id="p-restrictions" maxlength="4000">${esc(p.restrictions)}</textarea></label>`,async()=>{const data={name:$('#p-name').value.trim(),email:$('#p-email').value.trim().toLowerCase(),goal:$('#p-goal').value.trim(),restrictions:$('#p-restrictions').value.trim()};if(!data.name)throw Error('Preencha o nome do paciente.');if(S.demo){if(existing)Object.assign(existing,data);else S.patients.push({id:uid(),clinic_id:S.clinic.id,clinician_id:'demo',...data});}else{if(existing)errorCheck(await db.from('patients').update(data).eq('id',existing.id));else errorCheck(await db.from('patients').insert({...data,clinic_id:S.clinic.id,clinician_id:S.user.id}));await loadData();}render();toast(existing?'Cadastro atualizado.':'Paciente cadastrado.');});}
async function saveLog(change){const prev=logToday();if(S.demo){const next={...prev,...change};if('waterDelta'in change){next.water_ml=Math.max(0,Math.min(20000,(prev.water_ml||0)+change.waterDelta));delete next.waterDelta;}if(change.mealId){next.meals=[...(prev.meals||[])].filter(x=>x!==change.mealId);if(change.completed)next.meals.push(change.mealId);delete next.mealId;delete next.completed;}let i=S.logs.findIndex(x=>x.patient_id===next.patient_id&&x.day===next.day);if(i<0)S.logs.push(next);else S.logs[i]=next;}else{if(navigator.onLine&&queueCount())await syncQueue();const operation={operationId:uid(),patientId:prev.patient_id,day:prev.day,patch:change};if(!navigator.onLine){enqueue(operation);applyLocalLog(prev,change);S.offline=true;toast('Registro guardado no aparelho. Será enviado ao reconectar.');}else{try{errorCheck(await db.rpc('record_log_once',{p_operation_id:operation.operationId,p_patient_id:operation.patientId,p_day:operation.day,p_patch:operation.patch}));await loadData();}catch(e){enqueue(operation);toast('Registro mantido na fila para conferir e sincronizar.');throw e;}}}render();}
function moodName(m){return ({great:'Muito bem',good:'Bem',neutral:'Regular',low:'Com dificuldade',bad:'Preciso de apoio'})[m]||m||'';}
function checkinModal(){const l=logToday();modal('Meu check-in de hoje',`<label>Como você se sente?<select id="check-mood">${[['great','Muito bem'],['good','Bem'],['neutral','Regular'],['low','Com dificuldade'],['bad','Preciso de apoio']].map(([v,n])=>`<option value="${v}" ${l.mood===v?'selected':''}>${n}</option>`).join('')}</select></label><div class="form-grid"><label>Horas de sono (opcional)<input id="check-sleep" type="number" min="0" max="24" step="0.5" value="${typeof l.sleep==='number'?l.sleep:''}"></label><label>Peso em kg (opcional)<input id="check-weight" type="number" min="1" max="999" step="0.1" value="${l.weight||''}"></label></div><label>O que gostaria de compartilhar?<textarea id="check-note" maxlength="4000" placeholder="Como foi o dia? Teve alguma dificuldade?">${esc(l.note)}</textarea></label>`,async()=>{const before=stats().xp;await saveLog({mood:$('#check-mood').value,sleep:$('#check-sleep').value===''?null:Number($('#check-sleep').value),weight:$('#check-weight').value===''?null:Number($('#check-weight').value),note:$('#check-note').value.trim()});if(navigator.onLine||S.demo){const gained=Math.max(0,stats().xp-before);toast('Check-in registrado para sua nutri.'+(gained?' +'+gained+' XP de cuidado.':''));}});}
function appointmentModal(){if(!S.patients.length){toast('Cadastre um paciente antes de agendar.');return;}modal('Agendar consulta',`<label>Paciente<select id="appointment-patient">${S.patients.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><label>Data e horário<input id="appointment-time" type="datetime-local" required></label><label>Duração (min)<input id="appointment-duration" type="number" min="1" max="480" value="60" required></label><label>Observação<input id="appointment-note" maxlength="2000" placeholder="Consulta de retorno"></label>`,async()=>{const data={patient_id:$('#appointment-patient').value,start_at:new Date($('#appointment-time').value).toISOString(),note:$('#appointment-note').value.trim(),duration_minutes:Number($('#appointment-duration').value),status:'scheduled'};if(S.appointments.some(x=>(x.status||'scheduled')==='scheduled'&&Date.parse(x.start_at)<Date.parse(data.start_at)+data.duration_minutes*60000&&Date.parse(x.start_at)+(x.duration_minutes||60)*60000>Date.parse(data.start_at)))throw Error('Este horário se sobrepõe a outra consulta.');if(S.demo)S.appointments.push({id:uid(),...data});else{errorCheck(await db.from('appointments').insert({...data,clinician_id:S.user.id}));await loadData();}render();toast('Consulta agendada.');});}
function challengeModal(){modal('Novo desafio',`<label>Nome do desafio<input id="challenge-title" maxlength="200" required placeholder="Uma semana de diário"></label><label>O que acompanhar<select id="challenge-metric">${['nutriDias','nutriRegistros','habitosAgua','habitosSono','checkins'].map(m=>`<option value="${m}">${metricName(m)}</option>`).join('')}</select></label><label>Meta de registros<input id="challenge-target" type="number" min="1" max="10000" value="7" required></label>`,async()=>{const data={title:$('#challenge-title').value.trim(),metric:$('#challenge-metric').value,target:Number($('#challenge-target').value)};if(S.demo)S.challenges.push({id:uid(),...data});else{errorCheck(await db.from('challenges').insert({...data,clinic_id:S.clinic.id,owner_id:S.user.id}));await loadData();}render();toast('Desafio disponível no app do paciente.');});}
function addFoodModal(ri,ii=null){
 if(ii!==null){const input=$('[data-food-measure-quantity="'+ri+':'+ii+'"]')||$('[data-food-q="'+ri+':'+ii+'"]');if(input){try{parseFoodQuantity(input.value);}catch{input.focus();throw Error('Confira a quantidade do alimento principal antes de sugerir substituições.');}}}
 syncEditor();const draft=S.edit,patientId=S.selected,meal=draft.refeicoes[ri];
 if(ii!==null){
  const main=meal.itens[ii],snapshot=JSON.stringify(main),p=patient(),anamnesis=latestAnamnesis(S.records,p.id);
  if(main.substituicoes?.length>=12)throw Error('Use até 12 alternativas por alimento.');
  return foodSubstitutionModal({modal,uid,toast},{target:main,foods:nutritionCatalog(P.resources('food')),restrictions:[...new Set([p.restrictions,anamnesis?.data?.allergies].filter(Boolean).map(value=>value.trim()))].join(' · '),onSave:item=>{
   if(S.edit!==draft||S.selected!==patientId||S.edit.refeicoes[ri]!==meal||meal.itens[ii]!==main||JSON.stringify(main)!==snapshot)throw Error('O alimento ou o plano mudou. Abra novamente as sugestões.');
   main.substituicoes=main.substituicoes||[];if(main.substituicoes.length>=12)throw Error('Use até 12 alternativas por alimento.');
   main.substituicoes.push(item);cacheEditor();render();toast('Substituição adicionada ao rascunho.');
  }});
 }
 modal('Adicionar alimento',foodBrowserMarkup());
 bindFoodBrowser($('#food-browser'),{foods:nutritionCatalog(P.resources('food')),actionLabel:'Definir quantidade',onSelect:chosen=>foodPortionModal({modal,uid,toast},chosen,{title:'Definir alimento',onSave:item=>{
  if(S.edit!==draft||S.selected!==patientId||S.edit.refeicoes[ri]!==meal)throw Error('O plano mudou. Abra novamente o alimento.');
  if(meal.itens.length>=50)throw Error('Use até 50 alimentos por refeição.');meal.itens.push(item);
  cacheEditor();render();
 }})});
}
function editAlternative(ri,ii,ai){
 syncEditor();const item=S.edit.refeicoes[ri].itens[ii].substituicoes[ai];
 if(item.measurement){const draft=S.edit,main=draft.refeicoes[ri].itens[ii],snapshot=JSON.stringify(main);return foodPortionModal({modal,uid,toast},null,{item,title:'Editar substituição',note:'Esta opção substitui o alimento principal. Revise a adequação ao paciente.',renderComparison:next=>substitutionComparisonMarkup(main,next),onSave:next=>{if(S.edit!==draft||draft.refeicoes[ri]?.itens[ii]!==main||JSON.stringify(main)!==snapshot)throw Error('O plano mudou. Reabra a substituição.');S.edit.refeicoes[ri].itens[ii].substituicoes[ai]=next;cacheEditor();render();}});}
 modal('Editar substituição',`<p class="sub">Esta opção substitui o alimento principal. Não representa uma equivalência automática.</p><label>Alimento<input id="alt-name" required maxlength="200" value="${esc(item.nome)}"></label><div class="form-grid"><label>Quantidade de porções<input id="alt-quantity" required type="number" min="0.001" max="1000" step="any" value="${esc(item.qtd)}"></label><label>Medida de uma porção<input id="alt-portion" required maxlength="100" value="${esc(item.porcao)}" placeholder="Ex.: 100 g ou 1 unidade"></label></div><p class="sub">Ao mudar a medida, revise os valores por porção abaixo. Nenhuma conversão é feita automaticamente.</p><div class="form-grid">${[['k','Energia (kcal)'],['pt','Proteínas (g)'],['cb','Carboidratos (g)'],['g','Gorduras (g)']].map(([key,label])=>`<label>${label} por porção<input id="alt-${key}" type="number" required min="0" max="100000" step="any" value="${esc(item[key])}"></label>`).join('')}</div><label class="check-label"><input id="alt-reviewed" type="checkbox" required>Conferi a medida e os valores desta porção.</label>`,()=>{
   const next={...item,nome:$('#alt-name').value.trim(),porcao:$('#alt-portion').value.trim(),qtd:Number($('#alt-quantity').value)};
   for(const key of ['k','pt','cb','g'])next[key]=Number($('#alt-'+key).value);
   if(!$('#alt-reviewed').checked||!next.porcao||!MT_NUTRICAO.normalizaItem(next,true))throw Error('Confira o alimento, a porção e os valores informados.');
   // A manually revised measure cannot retain stale weight/household metadata.
   if(next.porcao!==item.porcao||next.nome!==item.nome){delete next.baseGramas;delete next.medidas;next.alimId=next.nome;}
   S.edit.refeicoes[ri].itens[ii].substituicoes[ai]=next;cacheEditor();render();
 });
}
function validateDraft(){for(const input of document.querySelectorAll('[data-food-measure-quantity]')){try{parseFoodQuantity(input.value);}catch{input.reportValidity();throw Error('Confira as quantidades dos alimentos antes de salvar.');}}if(!S.edit.titulo.trim())throw Error('Preencha o título do plano.');if(S.edit.refeicoes.length>12||S.edit.refeicoes.some(r=>r.itens.length>50))throw Error('Use até 12 refeições e 50 alimentos por refeição.');if(new TextEncoder().encode(JSON.stringify(S.edit)).length>200000)throw Error('O plano está muito grande. Reduza as orientações ou alternativas.');const err=MT_NUTRICAO.validaPlanoEntrada(S.edit);if(err)throw Error(err);if(S.edit.startOn&&S.edit.endOn&&S.edit.startOn>S.edit.endOn)throw Error('A revisão precisa ser depois do início do plano.');const water=S.edit.aguaMl;if(!Number.isFinite(water)||water<250||water>10000)throw Error('Confira a quantidade de água prescrita.');}
async function saveDraft(){syncEditor();validateDraft();if(S.demo){let d=S.plans.find(x=>x.id===S.draftId);if(d){d.data=structuredClone(S.edit);d.version++;}else{d={id:uid(),patient_id:S.selected,status:'draft',version:1,data:structuredClone(S.edit)};S.plans.push(d);}S.draftId=d.id;S.expectedVersion=d.version;}else{let d;if(S.draftId){const r=await db.from('plans').update({data:S.edit}).eq('id',S.draftId).eq('version',S.expectedVersion).select('*');d=errorCheck(r)[0];if(!d)throw Error('Este rascunho mudou em outra sessão. Abra o plano novamente antes de salvar.');}else{d=errorCheck(await db.from('plans').insert({patient_id:S.selected,clinician_id:S.user.id,status:'draft',data:S.edit}).select('*').single());}S.draftId=d.id;S.expectedVersion=d.version;await loadData();}sessionStorage.removeItem(draftKey());S.localDirty=false;render();toast('Rascunho salvo.');}
function reviewDraft(){
 syncEditor();validateDraft();const error=publicationError(S.edit);if(error)throw Error(error);
 const p=patient(),plan=structuredClone(S.edit),version=(published()?.version||0)+1;
 const review={patientId:S.selected,data:JSON.stringify(plan),draftId:S.draftId,expectedVersion:S.expectedVersion};
 const anamnesis=latestAnamnesis(S.records,p.id);
 modal('Revisar publicação',`<p><b>${esc(p.name)}</b> · ${esc(plan.titulo)}</p><p class="sub">Próxima versão: ${version}. O plano atual só muda após a confirmação abaixo.</p>${p.restrictions||anamnesis?.data?.allergies?`<div class="notice warning">${esc([p.restrictions,anamnesis?.data?.allergies].filter(Boolean).join(' · '))}</div>`:''}<div class="summary-line"><span>Vigência e revisão</span><span>${plan.startOn?dateLabel(plan.startOn):'Início não definido'} · ${plan.endOn?'revisar até '+dateLabel(plan.endOn):'revisão não definida'}</span></div><div class="summary-line"><span>Água prescrita</span><span>${plan.aguaMl} ml/dia</span></div>${planWeekTable(plan,validPlanDate(S.prescriptionDay)?S.prescriptionDay:today())}${renderPlanChanges(comparePlans(published()?.data,plan),{title:'O que muda nesta publicação',subtitle:published()?'Comparação com a versão publicada '+published().version:'Primeiro plano deste paciente'})}${plan.refeicoes.map(meal=>`<section class="meal"><h3>${esc(meal.hora)} · ${esc(meal.titulo)}</h3><p class="sub">${esc(mealDaysLabel(meal.dias))}</p>${meal.itens.map(item=>`<div class="summary-line"><span>${esc(item.nome)}</span><span>${esc(portionLabel(item))}</span></div>${item.substituicoes?.length?`<p class="sub">Alternativas: ${item.substituicoes.map(alt=>`${esc(alt.nome)} (${esc(portionLabel(alt))})`).join(' ou ')}</p>`:''}`).join('')}</section>`).join('')}<p style="white-space:pre-wrap">${esc(plan.orientacoes)}</p><label class="check-label"><input type="checkbox" id="confirm-plan-review" required>Revisei alimentos, porções, dias e restrições deste paciente.</label>`,()=>publishDraft(review));
 $('#modal-form button[type="submit"]').textContent='Confirmar publicação';$('#cancel-modal').textContent='Continuar editando';
}
function demoPlanSnapshot(plan){
 if(S.records.some(record=>record.patient_id===S.selected&&record.kind==='plan_version'&&record.data?.planId===plan.id&&record.data?.planVersion===plan.version))return;
 S.records.push({id:uid(),patient_id:S.selected,clinician_id:'demo',created_by:'demo',kind:'plan_version',title:`${plan.data.titulo} · versão ${plan.version}`,visibility:'patient',version:1,created_at:new Date().toISOString(),data:{planId:plan.id,planVersion:plan.version,plan:structuredClone(plan.data)}});
}
async function publishDraft(review){
 syncEditor();if(!review||review.patientId!==S.selected||review.draftId!==S.draftId||review.expectedVersion!==S.expectedVersion||review.data!==JSON.stringify(S.edit))throw Error('O rascunho mudou. Revise novamente antes de publicar.');
 const error=publicationError(S.edit);if(error)throw Error(error);await saveDraft();
 if(S.demo){let p=published();if(p){demoPlanSnapshot(p);p.data=structuredClone(S.edit);p.version++;}else{p={id:uid(),patient_id:S.selected,status:'published',version:1,data:structuredClone(S.edit)};S.plans.push(p);}demoPlanSnapshot(p);}
 else{errorCheck(await db.rpc('publish_patient_plan',{p_patient_id:S.selected,p_expected_version:S.expectedVersion}));await loadData();const d=S.plans.find(x=>x.id===S.draftId);if(d)S.expectedVersion=d.version;}
 render();toast('Plano publicado no app do paciente.');
}
async function showInvite(){if(S.demo){modal('Convite do paciente','<p class="sub">Na conta conectada, este convite vincula o paciente ao consultório usando o e-mail cadastrado. Convites da demonstração não permitem acesso real.</p>');return;}const data=errorCheck(await db.rpc('clinician_patient_details',{p_patient_id:S.selected}))[0];if(!data)throw Error('Paciente não disponível.');if(data.user_id){modal('Paciente conectado','<p class="sub">Este paciente já vinculou a conta ao consultório.</p>');return;}let code=data.invite_code;if(!code||new Date(data.invite_expires_at)<new Date()){const c=errorCheck(await db.rpc('rotate_patient_invite',{p_patient_id:S.selected}))[0];code=c.invite_code;}const inviteUrl=new URL(appBase.href);inviteUrl.searchParams.set('convite',code);const link=inviteUrl.href;modal('Convite do paciente',`<p class="sub">Compartilhe o link com ${esc(data.name)}. Ele precisa criar ou acessar uma conta com <b>${esc(data.email)}</b> e confirmar o e-mail. O convite expira em 7 dias.</p><label>Link de acesso<input id="invite-link" readonly value="${esc(link)}"></label><button class="btn primary" id="copy-invite">Copiar convite</button>`);$('#copy-invite').onclick=()=>run(async()=>{try{await navigator.clipboard.writeText(link);toast('Convite copiado.');}catch{$('#invite-link').select();toast('Selecione e copie o link de acesso.');}});}
async function updateClinic(change){if(S.demo)Object.assign(S.clinic,change);else{errorCheck(await db.from('clinics').update(change).eq('id',S.clinic.id));await loadData();}render();toast('Configuração atualizada.');}
