 if(S.page==='editor')document.querySelectorAll('#plan-title,#plan-water,#plan-notes,#plan-start,#plan-end,#plan-days,[data-meal-title],[data-meal-time],[data-meal-day]').forEach(e=>e.oninput=()=>syncEditor());
